def __init__(self, query: str, sources: List[str], llm_model: str, request_id: str):
    self.query = query
    self.sources = sources
    self.llm_model = llm_model
    self.request_id = request_id

def generate(self) -> Any:
    result = self._chain().invoke(
        input={
            "question": self.query,
            "sources": self.sources,
        }
    )

    if result == NONE_RESPONSE:
        return []

    return set(map(str.strip, result.split(",")))

def _chain(self):
    llm = get_llm_by_credentials(self.llm_model, streaming=False, request_id=self.request_id)

    return (
        {"question": itemgetter("question"), "sources": itemgetter("sources")}
        | KB_SOURCES_SELECTOR_PROMPT
        | llm

        input_tokens_used=None,
        tokens_used=0,
        success=True,
    )

def generate(self) -> GenerationResult:
    return self.invoke(self._get_inputs())

def stream(self):
    chunks_collector = []
    try:
        chain = self._chain.with_config(callbacks=[ChainStreamingCallback(self.thread_generator)])
        stream = chain.stream(
            input=self._get_inputs(),
            config=self._get_config(),
        )
        for chunk in stream:
            if not chunk:
                continue

            chunks_collector.append(chunk)

        if isinstance(chunk, dict):
            generated = json.dumps(chunk)
        elif isinstance(chunk, BaseModel):
            generated = chunk.model_dump_json()
        else:
            generated = "".join(chunks_collector)

        self.thread_generator.send(
            StreamedGenerationResult(
                generated=generated,
                generated_chunk="",
                last=True,
            ).model_dump_json()
        )
    except Exception as e:
        stacktrace = traceback.format_exc()
        error_message = str(e)
        exception_type = type(e).__name__
        chunks_collector.append(f"PureChain generation failed with error: {exception_type}: {error_message}")
        logger.error(f"PureChain generation failed with error: {stacktrace}", exc_info=True)
        self.thread_generator.send(
            StreamedGenerationResult(
                generated="".join(chunks_collector), generated_chunk="", last=True, debug={}
            ).model_dump_json()
        )
    finally:
        self.thread_generator.close()

def _build_chain(self) -> Runnable:
    """Helper method to build the chain - makes testing easier"""
    prompt = self._build_prompt_template()

    inputs = {
        "question": itemgetter("question"),
        "chat_history": (itemgetter("chat_history") | RunnableLambda(self._transform_history)),

    workflow_state: WorkflowState,
    *args,
    **kwargs,
):
    super().__init__(callbacks, workflow_execution_service, thought_queue, *args, **kwargs)
    self.workflow_state: WorkflowState = workflow_state
    self.request_id = workflow_execution_service.workflow_execution_id

