async def grade_evidence(message: str) -> LLMGradingDecision:
    """Grade one self-contained verification prompt."""
    try:
        response = await get_verification_grader().run(message, options=_GRADER_OPTIONS)
    except Exception as exc:
        filtered = _find_content_filter_error(exc)
        if filtered is not None:
            raise ContentFilteredError(
                f"{CONTENT_FILTER_MARKER}: Azure content safety blocked the "
                "grading request"
            ) from exc
        raise
    value = response.value
    if isinstance(value, LLMGradingDecision):
        return value
    if isinstance(value, Mapping):
        return LLMGradingDecision.model_validate(value)
    text = response.text.strip()
    if not text:
        raise ValueError("VerificationGrader returned an empty grading decision")
    return LLMGradingDecision.model_validate_json(text)

def output_chunk_content(self, content, print_stream, stream_callback):
    if content:
        if print_stream:
            print(content, end="", flush=True)
        if stream_callback:
            stream_callback(content)

def iterate_streaming_response(self, messages, print_stream, stream_callback):
    response = None
    previous_chunks = []
    self.log.debug(f"Streaming with LLM attributes: {self.llm.dict()}")
    provider_streaming_method = getattr(self.provider, "handle_streaming_chunk", None)
    for chunk in self.llm.stream(messages):
        if provider_streaming_method:
            content = provider_streaming_method(chunk, previous_chunks)
            response = content if not response else response + content
        elif isinstance(chunk, AIMessageChunk) or isinstance(chunk, AIMessage):
            content = chunk.content
            response = chunk if not response else response + chunk
        elif isinstance(chunk, str):
            content = chunk
            response = content if not response else response + content
        else:
            raise ValueError(f"Unexpected chunk type: {type(chunk)}")
        self.output_chunk_content(content, print_stream, stream_callback)
        if not self.streaming:
            if getattr(response, "tool_call_chunks", None):
                response = None
            util.print_status_message(False, "Generation stopped")
            break
        previous_chunks.append(chunk)
    return response

def execute_llm_streaming(self, messages):
    self.log.debug(f"Started streaming request at {util.current_datetime().isoformat()}")
    response = ""
    print_stream = self.request_overrides.get("print_stream", False)
    stream_callback = self.request_overrides.get("stream_callback", None)
    # Start streaming loop.
    self.streaming = True

    except ValueError as e:
        return False, messages, e
    finally:
        # End streaming loop.
        self.streaming = False
    self.log.debug(f"Stopped streaming response at {util.current_datetime().isoformat()}")
    return True, response, "Response received"

def execute_llm_non_streaming(self, messages):
    self.log.info("Starting non-streaming request")
    self.log.debug(f"Non-streaming with LLM attributes: {self.llm.dict()}")
    provider_non_streaming_method = getattr(self.provider, "handle_non_streaming_response", None)
    try:
        response = self.llm.invoke(messages)
        if provider_non_streaming_method:
            response = provider_non_streaming_method(response)
    except ValueError as e:
        return False, messages, e
    return True, response, "Response received"

def post_response(self, response_obj, new_messages):
    response_message, tool_calls = self.extract_message_content(response_obj)
    new_messages.append(response_message)

    if tool_calls:
        return self.handle_tool_calls(tool_calls, new_messages)

    if plugin.provider:
        return plugin.provider
    try:
        return plugin.context.get_using_provider(umo=session_id)
    except TypeError:
        return plugin.context.get_using_provider()


async def _get_summary_llm_response(
    plugin: "Mnemosyne",
    memory_text: str,
    *,
    persona_id: str | None = None,
    session_id: str = "",
    context_history: list[dict] | None = None,
) -> LLMResponse | None:
    """
    请求 LLM 进行记忆总结。

    Args:
        plugin: Mnemosyne 插件实例。
        memory_text: 需要总结的记忆文本。

    Returns:
        LLMResponse 对象，如果请求失败则为 None。
    """
    # logger = plugin.logger
    providers: list[tuple[str, Any]] = []
    try:
        primary_provider = _get_current_summary_provider(plugin, session_id)
        if primary_provider:
            providers.append(("主", primary_provider))
    except Exception as e:
        logger.error(f"获取 LLM Provider 时出错: {e}", exc_info=True)

    fallback_provider_id = plugin.config.get("summary_fallback_provider_id", "")
    if isinstance(fallback_provider_id, str) and fallback_provider_id.strip():
        try:
            fallback_provider = plugin.context.get_provider_by_id(
                fallback_provider_id.strip()
            )
            if fallback_provider and all(
                fallback_provider is not provider for _, provider in providers
            ):
                providers.append(("备用", fallback_provider))
            elif not fallback_provider:
                logger.warning(
                    f"未找到备用总结 Provider: {fallback_provider_id.strip()}"
                )
        except Exception as e:
            logger.error(f"获取备用总结 Provider 时出错: {e}", exc_info=True)

    if not providers:
        logger.error("无法获取用于总结记忆的 LLM Provider。")
        return None

    long_memory_prompt = plugin.config.get(
        "long_memory_prompt",
        "请将以下多轮对话历史总结为一段简洁、客观、包含关键信息的长期记忆条目:",
    )
    summary_llm_config = plugin.config.get("summary_llm_config", {})

    logger.debug(
        f"请求 LLM 总结短期记忆，提示: '{long_memory_prompt[:50]}...', 内容长度: {len(memory_text)}"
    )

    try:
        summary_contexts = [{"role": "system", "content": long_memory_prompt}]
        if plugin.config.get("use_summary_time_anchor", True):
            now_str = datetime.now().astimezone().isoformat(timespec="seconds")
            summary_contexts.append(
                {
                    "role": "system",
                    "content": (
                        f"当前绝对时间：{now_str}。"
                        "如果原始对话未明确给出具体日期/年份，禁止臆造精确日期；"
                        "请使用“近期/之前/后来”等相对表达。"
                    ),
                }
            )

        speaker_mapping = _build_summary_speaker_mapping_prompt(
            plugin,
            persona_id,
            session_id,
            context_history,
        )
        if speaker_mapping:
            summary_contexts.append(
                {"role": "system", "content": speaker_mapping}
            )

        for provider_kind, llm_provider in providers:
            try:
                llm_response = await llm_provider.text_chat(  # type: ignore
                    prompt=memory_text,
                    contexts=summary_contexts,
                    **summary_llm_config,
                )
                logger.debug(
                    f"{provider_kind} LLM 总结响应原始数据: {llm_response}"
                )
                if _summary_response_has_text(llm_response):
                    return llm_response
                logger.warning(f"{provider_kind}总结 Provider 返回空内容。")
            except Exception as e:
                logger.error(
                    f"{provider_kind}总结 Provider 请求失败: {e}",
                    exc_info=True,
                )
        return None
    except Exception as e:
        logger.error(f"构造总结请求时失败: {e}", exc_info=True)
        return None


