        )
        if resp.status_code != 200:
            raise RuntimeError(f"阿里云嵌入调用失败（模型: {self.model_name}）: {resp.message}")
        # DashScope 响应统一格式：{"embeddings": [{"embedding": [...], "text_index": 0}]}
        embeddings = resp.output.get("embeddings") or []
